    <!-- Chart code -->
    <script>
        am5.ready(function () {

// Create root element
            var root = am5.Root.new("childrenChart");
            /* remove amchart logo */
            root._logo.dispose();

// Set themes
// https://www.amcharts.com/docs/v5/concepts/themes/
            var myTheme = am5.Theme.new(root);

            myTheme.rule("Label").setAll({
                // fill: am5.color(0xFF0000),
                // fontSize: "1.5em"
            });

            root.setThemes([
                am5themes_Animated.new(root),
                am5themes_Responsive.new(root),
                myTheme
            ]);


// Create chart
// https://www.amcharts.com/docs/v5/charts/percent-charts/pie-chart/
            var chart = root.container.children.push(am5percent.PieChart.new(root, {
                layout: root.verticalLayout,
                innerRadius: am5.percent(50)
            }));

// Create series
// https://www.amcharts.com/docs/v5/charts/percent-charts/pie-chart/#Series
            var series = chart.series.push(am5percent.PieSeries.new(root, {
                valueField: "value",
                categoryField: "category",
                // alignLabels: false,
                // legendValueText: "{value}",
                // legendLabelText: "{category}",
            }));
            series.slices.template.setAll({
                templateField: "sliceSettings",
            });

            series.slices.template.setAll({
                strokeOpacity: 0,
                shadowColor: am5.color("#616262"),
                shadowBlur: 2,
                shadowOffsetX: 1,
                shadowOffsetY: 3,
            });
            // series.labels.template.setup = function(label, dataItem) {
            //     label.events.on("dataitemchanged", function(ev) {
            //         label.set("color", am5.color.new(root, {
            //             fill: ev.target.dataItem.get("slice").get("fill")
            //         }));
            //     });
            // }

            series.labels.template.setAll({
                textType: "circular",
                fontSize: 30,
                fontWeight: "700",
                // centerX: 0,
                // centerY: 0,
                text: "{value}%",
                templateField: "sliceSettings"
            });
// Set data
// https://www.amcharts.com/docs/v5/charts/percent-charts/pie-chart/#Setting_data
            series.data.setAll([
                {
                    value: 57,
                    category: "high school",
                    sliceSettings: {
                        fill: am5.color("#B2B2B2"),
                        stroke: am5.color("#B2B2B2"),
                    },
                },
                {
                    value: 13,
                    category: "kindergarten",
                    sliceSettings: {
                        fill: am5.color("#BC1818"),
                        stroke: am5.color("#B2B2B2")
                    },

                },
                {
                    value: 30,
                    category: "elemantry",
                    sliceSettings: {
                        fill: am5.color("#616262"),
                        stroke: am5.color("#B2B2B2")
                    },

                }
            ]);

// Create legend
// https://www.amcharts.com/docs/v5/charts/percent-charts/legend-percent-series/
            var legend = chart.children.unshift(am5.Legend.new(root, {
                centerX: am5.percent(62),
                x: am5.percent(50),
                marginTop: 25,
                layout: am5.GridLayout.new(root, {
                    maxColumns: 2,
                    fixedWidthGrid: true
                })
                // fillField: "color",
                // strokeField: "color",
            }));

            legend.data.setAll(series.dataItems);
            legend.valueLabels.template.set("forceHidden", true);
// Play initial series animation
// https://www.amcharts.com/docs/v5/concepts/animations/#Animation_of_series
            series.appear(1000, 100);
            // childrenChart.legend.labels.template.fontSize = 9;
            // childrenChart.update();

        }); // end am5.ready()
    </script>

